('9318', NULL, '9304', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'quote', 'Oberbürgermeisterin Dr. Katharina Vogt', '', 'Verwaltung soll einfach, verständlich und nah an den Menschen sein. Daran arbeiten wir jeden Tag.', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '100', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', 'Dr. Katharina Vogt, Oberbürgermeisterin', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9319', NULL, '9304', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Stadtrat & Verwaltung', '', '<p>An der Spitze der Verwaltung steht Oberbürgermeisterin Dr. Katharina Vogt. Sie leitet die Verwaltung und den Stadtrat.</p>\r\n<p>Der Stadtrat beschließt unter anderem den Haushalt, Bebauungspläne und große Bauprojekte. Die Sitzungen sind in der Regel öffentlich. Die Termine finden Sie im Veranstaltungskalender.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Rund 720 Beschäftigte arbeiten in der Stadtverwaltung Falkenquell. Der Stadtrat mit 42 Mitgliedern entscheidet über die wichtigen Fragen der Stadt.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9320', NULL, '9306', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Ferienbetreuung', '', '<p>Die Anmeldung für das Ferienprogramm im Sommer startet am 1. März. Die Plätze werden nach Eingang vergeben.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9321', NULL, '9306', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Bildung in Zahlen', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '4', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9322', NULL, '9306', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Angebote', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '6', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9323', NULL, '9306', '1793788704', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Familie, Bildung & Soziales', '', '<p>Falkenquell ist eine familienfreundliche Stadt. Hier finden Sie Informationen zu Betreuung, Schulen und Beratungsangeboten für alle Lebensphasen.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
