('9325', NULL, '9307', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'texticon', 'Natur und Erholung', '', '<p>Parks, Grünzüge und der Falkenbach bieten viele Möglichkeiten für Bewegung und Erholung im Stadtgebiet.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/leaf.svg', 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/', '0', 'left', 'default', 'circle', '#FFFFFF', '#094277', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9326', NULL, '9307', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Orte zum Entdecken', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '6', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9327', NULL, '9307', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Freizeit & Kultur', '', '<p>Das Kulturhaus am Markt ist das kulturelle Zentrum der Stadt. Hier finden Konzerte, Lesungen und Ausstellungen statt. Über 120 Vereine bieten Sport, Musik und Begegnung an.</p>\r\n<p>Wer lieber draußen ist, findet am Falkenbach, im Falkenpark und im Falkenwald Wege für Spaziergänge, Radtouren und Wanderungen.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Ob Konzert im Kulturhaus, ein Nachmittag im Naturbad oder eine Wanderung im Falkenwald: In Falkenquell gibt es viel zu entdecken.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9328', NULL, '9308', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'accordion', 'Parken', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '3', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9329', NULL, '9308', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Baustelle Mühlenbrücke', '', '<p>Die Mühlenbrücke ist wegen Bauarbeiten für den Autoverkehr gesperrt. Fußgänger und Radfahrende können die Brücke weiter nutzen. Die Umleitung ist ausgeschildert.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9330', NULL, '9308', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'texticon', 'Mehr Platz fürs Rad', '', '<p>Falkenquell baut das Radwegenetz schrittweise aus. Neue Verbindungen sollen Wohnquartiere besser mit Innenstadt, Bahnhof und Schulen verbinden.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/map.svg', 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/', '0', 'left', 'default', 'circle', '#FFFFFF', '#094277', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9331', NULL, '9308', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Unterwegs in Falkenquell', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '4', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9332', NULL, '9308', '1793716556', '1793716556', '0', '0', '0', '0', '0', '16', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Mobilität', '', '<p>Das Mobilitätskonzept Falkenquell 2035 beschreibt, wie sich Verkehr in der Stadt entwickeln soll. Ziel sind sichere Radwege, ein dichter Bustakt und weniger Verkehr in der Innenstadt.</p>\r\n<p>Bürgerinnen und Bürger haben das Konzept in mehreren Workshops mitgestaltet. Den aktuellen Stand finden Sie unter <a href=\"t3://page?uid=9318\">Bürgerbeteiligung</a>.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Bus, Bahn, Rad oder Auto: In Falkenquell kommen Sie auf vielen Wegen ans Ziel. Mit dem Mobilitätskonzept 2035 plant die Stadt die nächsten Schritte.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9333', NULL, '9310', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Sehenswürdigkeiten', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '6', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9334', NULL, '9310', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'accordion', 'Die Stadtteile', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '8', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9335', NULL, '9310', '1793788704', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Leben am Falkenbach', '', '<p>Der Falkenbach prägt das Stadtbild von Falkenquell. Entlang des Ufers verbinden Grünanlagen, Wege und kleine Plätze die Innenstadt mit den angrenzenden Stadtteilen.</p>\r\n<p>In den vergangenen Jahren wurden mehrere Abschnitte des Ufers neu gestaltet. Neue Sitzmöglichkeiten, zusätzliche Bäume und der ausgebaute Radweg machen den Falkenbach zu einem wichtigen Freizeit- und Verbindungsraum.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9336', NULL, '9310', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Zahlen & Fakten', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '4', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9337', NULL, '9310', '1793716556', '1793716556', '0', '0', '0', '0', '0', '16', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Stadtportrait', '', '<p>Quellen und Mühlen am Falkenbach brachten der Stadt über Jahrhunderte Arbeit und Wohlstand. Im 19. Jahrhundert wurde Falkenquell zu einem regionalen Zentrum für Handwerk und Maschinenbau. Aus dieser Zeit stammt auch das Rathaus am Marktplatz.</p>\r\n<p>Heute verbindet die Stadt historische Gebäude mit neuen Wohnquartieren und Gewerbeflächen. Der Falkenbach ist wieder ein Ort zum Spazieren, Radfahren und Verweilen.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Falkenquell liegt an einer alten Handelsstraße zwischen Falkenbach und Falkenwald. Die Stadt wurde im frühen 13. Jahrhundert zum ersten Mal erwähnt.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9338', NULL, '9311', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Innenstadt gemeinsam gestalten', '', '<p>Im Rahmen der Innenstadtentwicklung plant die Stadt einen neuen Marktplatz mit Bäumen, Sitzplätzen und Wasserspielen. Parkplätze sollen in die nahen Parkhäuser verlagert werden.</p>\r\n<p>Bis Ende Januar können Sie Vorschläge einreichen und über die Entwürfe mitdiskutieren. Alle Informationen finden Sie unter <a href=\"t3://page?uid=9318\">Bürgerbeteiligung</a>.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Der Marktplatz soll grüner und für alle besser nutzbar werden. Ihre Ideen fließen in die Planung ein.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9339', NULL, '9311', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Förderung für Hausbesitzer', '', '<p>Die Stadt fördert Dach- und Fassadenbegrünung mit bis zu 50 Prozent der Kosten. Anträge können Sie das ganze Jahr stellen.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'success', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9340', NULL, '9311', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Aktuelle Projekte', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '3', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9341', NULL, '9311', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Unsere Schwerpunkte', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '3', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9342', NULL, '9311', '1793788704', '1793716556', '0', '0', '0', '0', '0', '16', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Klimaschutz & Stadtentwicklung', '', '<p>Falkenquell will bis 2040 klimaneutral werden. Dafür hat der Stadtrat ein kommunales Klimaschutzprogramm beschlossen.</p>\r\n<p>Die Stadt saniert eigene Gebäude, baut Solaranlagen und schafft mehr Grün in der Innenstadt. Viele Maßnahmen gelingen nur gemeinsam mit Bürgerinnen, Bürgern und Unternehmen.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9343', NULL, '9312', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'texticon', 'Ihr Kontakt zur Wirtschaftsförderung', '', '<p>Wirtschaftsförderung Falkenquell<br />Rathaus, Marktplatz 1<br />Telefon: 0 54 21 / 30 00-400<br />E-Mail: <a href=\"mailto:wirtschaft@falkenquell.example\">wirtschaft@falkenquell.example</a></p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/briefcase.svg', 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/', '0', 'left', 'default', 'circle', '#FFFFFF', '#094277', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9344', NULL, '9312', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Flächen und Angebote', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '3', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9345', NULL, '9312', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Gute Gründe für Falkenquell', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '3', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9346', NULL, '9312', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Wirtschaftsstandort', '', '<p>Über 2.300 Unternehmen haben ihren Sitz in Falkenquell. Viele davon sind familiengeführt und seit Jahrzehnten in der Region verwurzelt.</p>\r\n<p>Die Wirtschaftsförderung hilft bei der Suche nach Flächen, bei Genehmigungen und bei Förderanträgen. Für Gründungen gibt es eine eigene Beratung.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Falkenquell ist ein Standort mit starkem Mittelstand. Maschinenbau, IT, Umwelttechnik und Gesundheitswirtschaft prägen die Wirtschaft der Stadt.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9347', NULL, '9314', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'News', '', '<p>Aktuelle Meldungen aus Rathaus und Stadtgesellschaft.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9348', NULL, '9315', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Veranstaltungen', '', '<p>Konzerte, Märkte, Führungen und Sitzungen des Stadtrats: Hier finden Sie alle Termine in Falkenquell.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9349', NULL, '9316', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Amtsblatt per E-Mail', '', '<p>Sie möchten keine Ausgabe verpassen? Schreiben Sie an <a href=\"mailto:amtsblatt@falkenquell.example\">amtsblatt@falkenquell.example</a>. Wir schicken Ihnen jede neue Ausgabe zu.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0');
