('9350', NULL, '9316', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Amtsblatt', '', '<p>Im Amtsblatt veröffentlicht die Stadt Falkenquell amtliche Bekanntmachungen, Satzungen und Beschlüsse des Stadtrats. Es erscheint einmal im Monat.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
