('9352', NULL, '9318', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Laufende Beteiligungen', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '3', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9353', NULL, '9318', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'So läuft die Beteiligung', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '3', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9354', NULL, '9318', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'quote', 'Stimme zur Innenstadt', '', 'Unser Ziel ist eine Innenstadt, in der sich Menschen gerne aufhalten und ihre täglichen Wege gut erledigen können.', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '100', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', 'Dr. Katharina Vogt, Oberbürgermeisterin', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9355', NULL, '9318', '1793716556', '1793716556', '0', '0', '0', '0', '0', '16', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Bürgerbeteiligung', '', '<p>Aktuell läuft die Beteiligung zur Neugestaltung des Marktplatzes. Der Platz soll grüner werden und mehr Raum zum Verweilen bieten.</p>\r\n<p>Ihre Vorschläge sammelt die Stadt online und in Workshops vor Ort. Die Ergebnisse fließen in die Planung ein, über die am Ende der Stadtrat entscheidet.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Falkenquell plant mit seinen Bürgerinnen und Bürgern. Bei großen Projekten können Sie Ideen einbringen, Entwürfe kommentieren und mitdiskutieren.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9356', NULL, '9319', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Bei Gefahr', '', '<p>Besteht eine akute Gefahr, zum Beispiel durch einen umgestürzten Baum auf der Straße? Rufen Sie bitte sofort die Polizei unter 110 an.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9357', NULL, '9319', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'form_formframework', '', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\"?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"settings.persistenceIdentifier\"><value index=\"vDEF\">9300</value></field><field index=\"settings.overrideFinishers\"><value index=\"vDEF\">0</value></field></language></sheet></data></T3FlexForms>\n', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9358', NULL, '9319', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Mangel melden', '', '<p>Ist Ihnen eine defekte Straßenlaterne, eine beschädigte Bank oder eine andere Auffälligkeit im öffentlichen Raum aufgefallen? Teilen Sie uns den Standort und eine kurze Beschreibung mit.</p>\r\n<p>Ihre Meldung geht direkt an die zuständige Stelle der Stadtverwaltung.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9359', NULL, '9320', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'accordion', 'Häufige Fragen', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '4', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9360', NULL, '9320', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Straßensperrungen', '', '<p>Während des Stadtfests ist die Innenstadt für den Autoverkehr gesperrt. Busse fahren Umleitungen. Nutzen Sie bitte die Park-and-Ride-Plätze am Bahnhof.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9361', NULL, '9320', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Programm', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '4', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9362', NULL, '9320', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Stadtfest Falkenquell 2027', '', '<p>Auf drei Bühnen spielen Bands aus der Region. Vereine stellen sich vor, und auf dem Kunsthandwerkermarkt gibt es Handgemachtes aus Falkenquell und Umgebung.</p>\r\n<p>Am Sonntag lädt der Lindenpark zum Familientag mit Spielen, Mitmachaktionen und Kinderprogramm ein. Den Abschluss bildet das Lichterfest am Falkenbach.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Vom 25. bis 27. Juni 2027 feiert Falkenquell sein Stadtfest. Drei Tage lang verwandeln sich Alter Markt, Falkenpark und Quellenpromenade in eine große Festmeile.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9363', NULL, '9321', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'accordion', 'Häufige Fragen zur Förderung', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '3', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9364', NULL, '9321', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Förderprogramm', '', '<p>Für Dach-, Fassaden- und Hofbegrünung übernimmt die Stadt bis zu 50 Prozent der Kosten, höchstens 5.000 Euro je Grundstück.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'success', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9365', NULL, '9321', '1793716556', '1793716556', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Projekte', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '3', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9366', NULL, '9321', '1793716556', '1793716556', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Was Sie selbst tun können', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '3', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9367', NULL, '9321', '1793716556', '1793716556', '0', '0', '0', '0', '0', '16', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Falkenquell wird grün', '', '<p>Heiße Sommer und Starkregen zeigen, wie wichtig Grün in der Stadt ist. Bäume spenden Schatten, Grünflächen nehmen Regenwasser auf und kühlen die Umgebung.</p>\r\n<p>Mit dem Programm „Falkenquell wird grün“ pflanzt die Stadt bis 2028 300 neue Bäume. Dazu kommen begrünte Haltestellen, Schulhöfe und Plätze.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Gemeinsam für eine klimafreundliche Stadt: Mit neuen Bäumen, entsiegelten Flächen und Förderung für private Begrünung wird Falkenquell Schritt für Schritt grüner.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9368', NULL, '9322', '1793716556', '1793716556', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'accordion', 'Häufige Fragen', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '3', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9369', NULL, '9322', '1793716556', '1793716556', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'texticon', 'Neubürgerempfang', '', '<p>Zweimal im Jahr lädt die Oberbürgermeisterin alle neuen Einwohnerinnen und Einwohner ins Rathaus ein. Bei einer Stadtführung lernen Sie Falkenquell kennen. Die Einladung erhalten Sie nach Ihrer Anmeldung per Post.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/ios-people.svg', 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/', '0', 'left', 'default', 'circle', '#FFFFFF', '#094277', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
