('9379', NULL, '9316', '1793719539', '1793719451', '0', '0', '0', '0', '0', '192', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'uploads', 'Aktuelle Ausgaben', '', NULL, '0', '1', '1', '0', '0', NULL, '0', '1', '0', '3', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '1', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9380', NULL, '9310', '1793788704', '1793787196', '0', '0', '0', '0', '0', '512', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'image', 'Impressionen', '', NULL, '0', '0', '0', '0', '3', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9381', NULL, '9334', '1793789794', '1793789794', '0', '0', '0', '0', '0', '256', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'texticon', 'Kontakt', '', '<p>Falkenquell Brunnen &amp; Brauerei GmbH<br />Brunnenweg 20<br />Telefon: 0 54 21 / 9 87-0<br />E-Mail: <a href=\"mailto:info@falkenquell-brunnen.example\">info@falkenquell-brunnen.example</a></p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/briefcase.svg', 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/', '0', 'left', 'default', 'circle', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9382', NULL, '9334', '1793789794', '1793789794', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'panel', 'Führungen durch Brunnen und Brauerei', '', '<p>Von April bis Oktober bietet das Unternehmen am ersten Samstag im Monat eine Führung an. Sie dauert etwa zwei Stunden und führt vom Brunnenhaus über die Abfüllung bis ins Sudhaus.</p>\r\n<p>Die Teilnahme ist kostenlos, die Plätze sind begrenzt. Bitte melden Sie sich telefonisch oder per E-Mail beim Unternehmen an. Gruppen ab zehn Personen können eigene Termine vereinbaren.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9383', NULL, '9334', '1793789818', '1793789794', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'card_group', 'Was in Falkenquell entsteht', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"align\"><value index=\"vDEF\">left</value></field><field index=\"columns\"><value index=\"vDEF\">3</value></field></language></sheet></data></T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '3', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9384', NULL, '9334', '1793790110', '1793789794', '0', '0', '0', '0', '0', '32', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Wasser aus der Falkenquelle', '', '<p>Das Mineralwasser stammt aus drei Brunnen am Rand des Falkenwalds. Sie fördern Wasser aus rund 180 Metern Tiefe, das dort über Jahrhunderte durch Sandstein gefiltert wurde. Abgefüllt wird es direkt vor Ort.</p>\r\n<p>Rund um die Brunnen gilt ein Wasserschutzgebiet. Stadt und Unternehmen arbeiten eng zusammen, damit Landwirtschaft, Wald und neue Bauflächen das Grundwasser nicht belasten.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9385', NULL, '9334', '1793789818', '1793789794', '0', '0', '0', '0', '0', '16', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'icon_group', 'Das Unternehmen in Zahlen', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '4', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9386', NULL, '9334', '1793789794', '1793789794', '0', '0', '0', '0', '0', '8', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Falkenquell Brunnen & Brauerei', '', '<p>Die Falkenquell Brunnen &amp; Brauerei ist der größte private Arbeitgeber der Stadt. Rund 480 Menschen arbeiten hier in der Abfüllung, im Sudhaus, in der Logistik und in der Verwaltung. Unter dem Namen Falkenquell vertreibt das Unternehmen Mineralwasser und Bier in der ganzen Region.</p>\r\n<p>Gegründet wurde der Betrieb 1874 als kleine Brauerei am Brunnenweg. Wenige Jahre später kam die Abfüllung des Quellwassers hinzu, dem die Stadt ihren Namen verdankt. Das Unternehmen ist bis heute in Familienbesitz.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9387', NULL, '9312', '1793790110', '1793789794', '0', '0', '0', '0', '0', '192', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Arbeitgeber mit Tradition', '', '<p>Größter privater Arbeitgeber in Falkenquell ist die Falkenquell Brunnen &amp; Brauerei mit rund 480 Beschäftigten. Seit 1874 wird am Brunnenweg Bier gebraut, wenig später kam die Abfüllung des Mineralwassers hinzu.</p>\r\n<p>Mehr über das Unternehmen, seine Produkte und die Ausbildung lesen Sie auf der Seite <a href=\"t3://page?uid=9334\">Falkenquell Brunnen &amp; Brauerei</a>.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9388', NULL, '9335', '1793950872', '1793950872', '0', '0', '0', '0', '0', '64', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textteaser', 'Newsletter der Stadt Falkenquell', '', '<p>Was im Stadtrat beschlossen wurde, wo demnächst gebaut wird und welche Termine anstehen, erfahren Sie mit dem Newsletter zuerst. Sie müssen nicht selbst nachsehen, sondern bekommen alles kompakt zusammengefasst und mit Links zu den Details.</p>\r\n<p>Der Newsletter erscheint am ersten Donnerstag im Monat. Bei wichtigen Themen, etwa Straßensperrungen oder kurzfristigen Änderungen im Bürgerbüro, schicken wir zusätzlich eine kurze Sonderausgabe.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '1', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', 'Einmal im Monat das Wichtigste aus Rathaus und Stadt direkt in Ihr Postfach: kostenlos, kurz und jederzeit abbestellbar.', '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9389', NULL, '9335', '1793950872', '1793950872', '0', '0', '0', '0', '0', '128', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Das erwartet Sie', '', '<ul><li><strong>Neues aus dem Rathaus:</strong> Beschlüsse des Stadtrats, neue Online-Dienste und geänderte Öffnungszeiten</li><li><strong>Termine:</strong> Veranstaltungen, Märkte und Feste der nächsten Wochen, vom Wochenmarkt bis zum Stadtfest</li><li><strong>Baustellen und Verkehr:</strong> geplante Sperrungen und Umleitungen rechtzeitig vorab</li><li><strong>Mitmachen:</strong> laufende Bürgerbeteiligungen und die Fristen, bis zu denen Sie Ihre Ideen einbringen können</li><li><strong>Amtsblatt:</strong> ein Hinweis, sobald eine neue Ausgabe erschienen ist</li></ul>\r\n<p>Ihre E-Mail-Adresse nutzen wir nur für den Versand des Newsletters und geben sie nicht weiter. Mehr dazu lesen Sie in den <a href=\"t3://page?uid=9329\">Datenschutzhinweisen</a>.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9390', NULL, '9335', '1793950872', '1793950872', '0', '0', '0', '0', '0', '192', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'form_formframework', 'Jetzt anmelden', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '0', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\"?>\n<T3FlexForms><data><sheet index=\"sDEF\"><language index=\"lDEF\"><field index=\"settings.persistenceIdentifier\"><value index=\"vDEF\">9302</value></field><field index=\"settings.overrideFinishers\"><value index=\"vDEF\">0</value></field></language></sheet></data></T3FlexForms>\n', '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9391', NULL, '9300', '1793950872', '1793950872', '0', '0', '0', '0', '0', '16', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Stadt Falkenquell', '', '<p>Rathaus<br />Marktplatz 1<br />05421 Falkenquell</p>\r\n<p>Telefon: 0 54 21 / 30 00-0<br />E-Mail: <a href=\"mailto:info@falkenquell.example\">info@falkenquell.example</a></p>\r\n<p>Bürgerbüro: Mo bis Fr 8 bis 12 Uhr, Do zusätzlich 14 bis 18 Uhr</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '10', '', '', '0', '100', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9392', NULL, '9300', '1793950872', '1793950872', '0', '0', '0', '0', '0', '8', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Schnell gefunden', '', '<ul><li><a href=\"t3://page?uid=9302\">Bürgerbüro</a></li><li><a href=\"t3://page?uid=9303\">Dienstleistungen &amp; Formulare</a></li><li><a href=\"t3://page?uid=9319\">Mängelmelder</a></li><li><a href=\"t3://page?uid=9316\">Amtsblatt</a></li><li><a href=\"t3://page?uid=9314\">News</a></li><li><a href=\"t3://page?uid=9315\">Veranstaltungen</a></li><li><a href=\"t3://page?uid=9318\">Bürgerbeteiligung</a></li><li><a href=\"t3://page?uid=9310\">Stadtportrait</a></li></ul>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '11', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
('9393', NULL, '9300', '1793950872', '1793950872', '0', '0', '0', '0', '0', '4', '0', '0', '0', '0', NULL, '', '0', '0', '0', '0', 'textpic', 'Newsletter', '', '<p>Einmal im Monat das Wichtigste aus Rathaus und Stadt: Termine, Baustellen, Beteiligungen.</p>\r\n<p><a href=\"t3://page?uid=9335\" class=\"btn btn-secondary\">Newsletter abonnieren</a></p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', NULL, NULL, '12', '', '', '0', '0', '1', '0', NULL, '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', NULL, '0', NULL, '1.3333333333333', '10', '', '', '', 'default', NULL, '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', NULL, '0', NULL, NULL, NULL, '0'),
