('9397', NULL, '9329', '1793957032', '1793957032', '0', '0', '0', '0', '', '512', '0', '1', '9302', '9302', NULL, '', '0', '0', '0', '0', 'textpic', 'Data Protection', '', '<p>Content to follow: information on the processing of personal data.</p>', '0', '0', '0', '0', '0', NULL, '0', '2', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '', '', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '4', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
