('9410', NULL, '9303', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9315', '9315', NULL, '', '0', '0', '0', '0', 'textpic', 'Services & Forms', '', '<p>Many matters can already be dealt with online. Here you will find the city\'s most common services with all the documents you need.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
