('9412', NULL, '9304', '1793957032', '1793957032', '0', '0', '0', '0', '', '192', '0', '1', '9317', '9317', NULL, '', '0', '0', '0', '0', 'card_group', 'Departments and Specialist Areas', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"align\">\n                    <value index=\"vDEF\">left</value>\n                </field>\n                <field index=\"columns\">\n                    <value index=\"vDEF\">3</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '6', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9413', NULL, '9304', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9318', '9318', NULL, '', '0', '0', '0', '0', 'quote', 'Lord Mayor Dr Katharina Vogt', '', 'Administration should be simple, easy to understand and close to the people. We work on that every day.', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '100', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', 'Dr Katharina Vogt, Lord Mayor', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9414', NULL, '9304', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9319', '9319', NULL, '', '0', '0', '0', '0', 'textteaser', 'Town Council & Administration', '', '<p>At the head of the administration is the Lord Mayor, Dr Katharina Vogt. She leads the administration and the Town Council.</p>\r\n<p>The Town Council decides, among other things, on the budget, development plans and major construction projects. The meetings are generally open to the public. You can find the dates in the events calendar.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', 'Around 720 employees work in Falkenquell’s city administration. The Town Council, with 42 members, decides on the important matters of the town.', '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9415', NULL, '9306', '1793957032', '1793957032', '0', '0', '0', '0', '', '512', '0', '1', '9320', '9320', NULL, '', '0', '0', '0', '0', 'panel', 'Holiday Childcare', '', '<p>Registration for the summer holiday programme opens on 1 March. Places are allocated on a first-come, first-served basis.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
