('9417', NULL, '9306', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9322', '9322', NULL, '', '0', '0', '0', '0', 'card_group', 'Offers', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"align\">\n                    <value index=\"vDEF\">left</value>\n                </field>\n                <field index=\"columns\">\n                    <value index=\"vDEF\">3</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '6', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9418', NULL, '9306', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9323', '9323', NULL, '', '0', '0', '0', '0', 'textpic', 'Family, Education & Social Affairs', '', '<p>Falkenquell is a family-friendly town. Here you will find information on childcare, schools and advisory services for all stages of life.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9419', NULL, '9307', '1793957032', '1793957032', '0', '0', '0', '0', '', '512', '0', '1', '9324', '9324', NULL, '', '0', '0', '0', '0', 'accordion', 'Opening hours', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '3', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9420', NULL, '9307', '1793957032', '1793957032', '0', '0', '0', '0', '', '192', '0', '1', '9325', '9325', NULL, '', '0', '0', '0', '0', 'texticon', 'Nature and Recreation', '', '<p>Parks, green corridors and the Falkenbach offer many opportunities for exercise and relaxation across the town.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/leaf.svg', 'EXT:bootstrap_package/Resources/Public/Images/Icons/Ionicons/', '0', 'left', 'default', 'circle', '#FFFFFF', '#094277', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9421', NULL, '9307', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9326', '9326', NULL, '', '0', '0', '0', '0', 'card_group', 'Places to Discover', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"align\">\n                    <value index=\"vDEF\">left</value>\n                </field>\n                <field index=\"columns\">\n                    <value index=\"vDEF\">3</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '6', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9422', NULL, '9307', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9327', '9327', NULL, '', '0', '0', '0', '0', 'textteaser', 'Leisure & Culture', '', '<p>The cultural centre at the market square is the city’s cultural hub. Concerts, readings and exhibitions take place here. More than 120 clubs and associations offer sport, music and opportunities to meet others.</p>\r\n<p>If you prefer being outdoors, you will find routes for walks, cycle tours and hikes along the Falkenbach, in Falkenpark and in Falkenwald.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', 'Whether it is a concert at the cultural centre, an afternoon at the natural outdoor pool or a hike in Falkenwald: there is plenty to discover in Falkenquell.', '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
