('9424', NULL, '9308', '1793957032', '1793957032', '0', '0', '0', '0', '', '192', '0', '1', '9329', '9329', NULL, '', '0', '0', '0', '0', 'panel', 'Roadworks at Mühlenbrücke', '', '<p>Mühlenbrücke is closed to car traffic due to roadworks. Pedestrians and cyclists can continue to use the bridge. The diversion is signposted.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0');
