('9449', NULL, '9318', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9354', '9354', NULL, '', '0', '0', '0', '0', 'quote', 'A Voice for the Town Centre', '', 'Our aim is a town centre where people enjoy spending time and can go about their daily errands with ease.', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '100', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', 'Dr Katharina Vogt, Lord Mayor', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0');
