('9450', NULL, '9318', '1793957032', '1793957032', '0', '0', '0', '0', '', '24', '0', '1', '9355', '9355', NULL, '', '0', '0', '0', '0', 'textteaser', 'Public participation', '', '<p>Public participation in the redesign of the market square is currently underway. The square is to become greener and offer more space to linger.</p>\r\n<p>The town is gathering your suggestions online and in workshops on site. The results will feed into the planning, on which the Town Council will make the final decision.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', 'Falkenquell plans together with its citizens. For major projects, you can contribute ideas, comment on drafts and join the discussion.', '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9451', NULL, '9319', '1793957032', '1793957032', '0', '0', '0', '0', '', '512', '0', '1', '9356', '9356', NULL, '', '0', '0', '0', '0', 'panel', 'In an Emergency', '', '<p>Is there an acute danger, for example due to a fallen tree on the road? Please call the police immediately on 110.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9452', NULL, '9319', '1793957032', '1793957032', '0', '0', '0', '0', '', '192', '0', '1', '9357', '9357', NULL, '', '0', '0', '0', '0', 'form_formframework', '', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\"?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"settings.persistenceIdentifier\">\n                    <value index=\"vDEF\">9301</value>\n                </field>\n                <field index=\"settings.overrideFinishers\">\n                    <value index=\"vDEF\">0</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>\n', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9453', NULL, '9319', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9358', '9358', NULL, '', '0', '0', '0', '0', 'textpic', 'Report a Problem', '', '<p>Have you noticed a defective street light, a damaged bench or another issue in a public space? Please tell us the location and provide a short description.</p>\r\n<p>Your report will be sent directly to the relevant department of the city administration.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9454', NULL, '9320', '1793957032', '1793957032', '0', '0', '0', '0', '', '512', '0', '1', '9359', '9359', NULL, '', '0', '0', '0', '0', 'accordion', 'Frequently Asked Questions', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '4', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9455', NULL, '9320', '1793957032', '1793957032', '0', '0', '0', '0', '', '192', '0', '1', '9360', '9360', NULL, '', '0', '0', '0', '0', 'panel', 'Road Closures', '', '<p>During the town festival, the town centre is closed to motor traffic. Buses are running on diversion routes. Please use the park-and-ride sites at the station.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'primary', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9456', NULL, '9320', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9361', '9361', NULL, '', '0', '0', '0', '0', 'icon_group', 'Programme', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '4', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9457', NULL, '9320', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9362', '9362', NULL, '', '0', '0', '0', '0', 'textteaser', 'Falkenquell Town Festival 2027', '', '<p>Bands from the region will perform on three stages. Local associations will introduce themselves, and the arts and crafts market will offer handmade goods from Falkenquell and the surrounding area.</p>\r\n<p>On Sunday, Lindenpark invites you to a family day with games, hands-on activities and a children’s programme. The festival concludes with the Festival of Lights at the Falkenbach.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', 'From 25 to 27 June 2027, Falkenquell celebrates its town festival. For three days, Alter Markt, Falkenpark and the Quellenpromenade will be transformed into one large festival area.', '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9458', NULL, '9321', '1793957032', '1793957032', '0', '0', '0', '0', '', '512', '0', '1', '9363', '9363', NULL, '', '0', '0', '0', '0', 'accordion', 'Frequently Asked Questions about Funding', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '3', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9459', NULL, '9321', '1793957032', '1793957032', '0', '0', '0', '0', '', '192', '0', '1', '9364', '9364', NULL, '', '0', '0', '0', '0', 'panel', 'Funding Programme', '', '<p>For green roofs, façades and courtyards, the town covers up to 50 per cent of the costs, up to a maximum of 5,000 euros per property.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'success', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9460', NULL, '9321', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9365', '9365', NULL, '', '0', '0', '0', '0', 'card_group', 'Projects', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"align\">\n                    <value index=\"vDEF\">left</value>\n                </field>\n                <field index=\"columns\">\n                    <value index=\"vDEF\">3</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '3', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9461', NULL, '9321', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9366', '9366', NULL, '', '0', '0', '0', '0', 'icon_group', 'What you can do yourself', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '3', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9462', NULL, '9321', '1793957032', '1793957032', '0', '0', '0', '0', '', '24', '0', '1', '9367', '9367', NULL, '', '0', '0', '0', '0', 'textteaser', 'Falkenquell is going green', '', '<p>Hot summers and heavy rainfall show how important green spaces are in the town. Trees provide shade, green areas absorb rainwater and cool the surroundings.</p>\r\n<p>With the “Falkenquell is going green” programme, the town will plant 300 new trees by 2028. In addition, there will be greened bus stops, school playgrounds and public squares.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', 'Working together for a climate-friendly town: with new trees, unsealed surfaces and support for private greening, Falkenquell is becoming greener step by step.', '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '2', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
