('9477', NULL, '9334', '1793957032', '1793957032', '0', '0', '0', '0', '', '192', '0', '1', '9382', '9382', NULL, '', '0', '0', '0', '0', 'panel', 'Guided tours of the well and brewery', '', '<p>From April to October, the company offers a guided tour on the first Saturday of each month. It lasts around two hours and takes you from the well house via the bottling plant to the brewhouse.</p>\r\n<p>Participation is free of charge, and places are limited. Please register with the company by telephone or by email. Groups of ten or more can arrange their own dates.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9478', NULL, '9334', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9383', '9383', NULL, '', '0', '0', '0', '0', 'card_group', 'What is being created in Falkenquell', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"align\">\n                    <value index=\"vDEF\">left</value>\n                </field>\n                <field index=\"columns\">\n                    <value index=\"vDEF\">3</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '3', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9479', NULL, '9334', '1793957032', '1793957032', '0', '0', '0', '0', '', '48', '0', '1', '9384', '9384', NULL, '', '0', '0', '0', '0', 'textpic', 'Water from the Falken Spring', '', '<p>The mineral water comes from three wells on the edge of Falkenwald. They draw water from a depth of around 180 metres, where it has been filtered through sandstone over centuries. It is bottled directly on site.</p>\r\n<p>A water protection area applies around the wells. The town and the company work closely together to ensure that agriculture, forest and new building land do not place a burden on the groundwater.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9480', NULL, '9334', '1793957032', '1793957032', '0', '0', '0', '0', '', '24', '0', '1', '9385', '9385', NULL, '', '0', '0', '0', '0', 'icon_group', 'The company in figures', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '4', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9481', NULL, '9334', '1793957032', '1793957032', '0', '0', '0', '0', '', '12', '0', '1', '9386', '9386', NULL, '', '0', '0', '0', '0', 'textteaser', 'Falkenquell Brunnen & Brauerei', '', '<p>Falkenquell Brunnen &amp; Brauerei is the city\'s largest private employer. Around 480 people work here in bottling, the brewhouse, logistics and administration. Under the name Falkenquell, the company sells mineral water and beer throughout the region.</p>\r\n<p>The business was founded in 1874 as a small brewery on Brunnenweg. A few years later, bottling of the spring water was added, to which the town owes its name. The company remains family-owned to this day.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9482', NULL, '9312', '1793957032', '1793957032', '0', '0', '0', '0', '', '176', '0', '1', '9387', '9387', NULL, '', '0', '0', '0', '0', 'textpic', 'Employer with tradition', '', '<p>The largest private employer in Falkenquell is Falkenquell Brunnen &amp; Brauerei, with around 480 employees. Beer has been brewed on Brunnenweg since 1874, and the bottling of mineral water was added shortly afterwards.</p>\r\n<p>You can read more about the company, its products and training opportunities on the <a href=\"t3://page?uid=9334\">Falkenquell Brunnen &amp; Brauerei</a> page.</p>', '0', '0', '0', '0', '1', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9483', NULL, '9335', '1793957032', '1793957032', '0', '0', '0', '0', '', '96', '0', '1', '9388', '9388', NULL, '', '0', '0', '0', '0', 'textteaser', 'Newsletter of the Town of Falkenquell', '', '<p>Find out first with the newsletter what was decided by the Town Council, where building work will be starting soon, and which dates are coming up. You do not need to check for yourself, but receive everything summarised compactly and with links to the details.</p>\r\n<p>The newsletter is published on the first Thursday of the month. For important topics, such as road closures or short-notice changes at the Citizens\' Office, we also send out a short special edition.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '1', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', 'Once a month, the most important news from the Town Hall and the town delivered straight to your inbox: free of charge, brief, and you can unsubscribe at any time.', '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9484', NULL, '9335', '1793957032', '1793957032', '0', '0', '0', '0', '', '112', '0', '1', '9389', '9389', NULL, '', '0', '0', '0', '0', 'textpic', 'What to expect', '', '<ul><li><strong>News from the Town Hall:</strong> Town Council decisions, new online services and changed opening hours</li><li><strong>Dates:</strong> events, markets and festivals in the coming weeks, from the weekly market to the town festival</li><li><strong>Roadworks and traffic:</strong> planned closures and diversions announced in good time</li><li><strong>Get involved:</strong> ongoing public participation opportunities and the deadlines by which you can submit your ideas</li><li><strong>Official Gazette:</strong> a notice as soon as a new issue has been published</li></ul>\r\n<p>We use your email address only to send the newsletter and do not pass it on. You can read more about this in the <a href=\"t3://page?uid=9329\">data protection information</a>.</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9485', NULL, '9335', '1793957032', '1793957032', '0', '0', '0', '0', '', '120', '0', '1', '9390', '9390', NULL, '', '0', '0', '0', '0', 'form_formframework', 'Register now', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\"?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"settings.persistenceIdentifier\">\n                    <value index=\"vDEF\">9303</value>\n                </field>\n                <field index=\"settings.overrideFinishers\">\n                    <value index=\"vDEF\">0</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>\n', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9486', NULL, '9300', '1793957032', '1793957032', '0', '0', '0', '0', '', '24', '0', '1', '9391', '9391', NULL, '', '0', '0', '0', '0', 'textpic', 'Town of Falkenquell', '', '<p>Town Hall<br />Market Square 1<br />05421 Falkenquell</p>\r\n<p>Telephone: 0 54 21 / 30 00-0<br />Email: <a href=\"mailto:info@falkenquell.example\">info@falkenquell.example</a></p>\r\n<p>Citizens\' Office: Mon to Fri 8 am to 12 noon, Thu additionally 2 pm to 6 pm</p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '10', '', '', '0', '100', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9487', NULL, '9300', '1793957032', '1793957032', '0', '0', '0', '0', '', '12', '0', '1', '9392', '9392', NULL, '', '0', '0', '0', '0', 'textpic', 'Quick links', '', '<ul><li><a href=\"t3://page?uid=9302\">Citizens\' Office</a></li><li><a href=\"t3://page?uid=9303\">Services &amp; Forms</a></li><li><a href=\"t3://page?uid=9319\">Report a Problem</a></li><li><a href=\"t3://page?uid=9316\">Official Gazette</a></li><li><a href=\"t3://page?uid=9314\">News</a></li><li><a href=\"t3://page?uid=9315\">Events</a></li><li><a href=\"t3://page?uid=9318\">Public Participation</a></li><li><a href=\"t3://page?uid=9310\">Town Profile</a></li></ul>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '11', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9488', NULL, '9300', '1793957032', '1793957032', '0', '0', '0', '0', '', '6', '0', '1', '9393', '9393', NULL, '', '0', '0', '0', '0', 'textpic', 'Newsletter', '', '<p>Once a month, the most important news from the Town Hall and the town: dates, roadworks, consultations.</p>\r\n<p><a href=\"t3://page?uid=9335\" class=\"btn btn-secondary\">Subscribe to the newsletter</a></p>', '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '12', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, NULL, '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '0', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0'),
('9489', NULL, '9302', '1793957032', '1793957032', '0', '0', '0', '0', '', '80', '0', '1', '9394', '9394', NULL, '', '0', '0', '0', '0', 'card_group', 'Opening Hours and Contact', '', NULL, '0', '0', '0', '0', '0', NULL, '0', '1', '0', '0', '0', 'default', '0', '', '', '', '', '0', '', '', '0', '0', '1', '0', '', '0', '', '', '', '0', '0', NULL, '<?xml version=\"1.0\" encoding=\"utf-8\" standalone=\"yes\" ?>\n<T3FlexForms>\n    <data>\n        <sheet index=\"sDEF\">\n            <language index=\"lDEF\">\n                <field index=\"align\">\n                    <value index=\"vDEF\">left</value>\n                </field>\n                <field index=\"columns\">\n                    <value index=\"vDEF\">2</value>\n                </field>\n            </language>\n        </sheet>\n    </data>\n</T3FlexForms>', '', '', NULL, '124', '0', '0', '0', '0', '0', '0', NULL, '1.3333333333333', '10', '', '', '', 'default', '', '', '', '0', '', 'default', 'default', '#FFFFFF', '#333333', '', '', '2', '0', '0', '0', '0', '0', 'default', '', '0', NULL, '0', '', '', '', '3', '', '', '', NULL, '', '0', '', '0', NULL, NULL, NULL, '0');

